import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/BDM.scaBLLhv.js";import{_ as r,o as i,c as n,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Stop sensore","description":"","frontmatter":{"source_hash":"2b688cafdf","source_commit":"ea9ce3a"},"headers":[],"relativePath":"it/use/stopsensor.md","filePath":"it/use/stopsensor.md"}'),t={name:"it/use/stopsensor.md"};function l(p,e,c,d,m,u){return i(),n("div",null,[...e[0]||(e[0]=[s('<p>Fermare un sensore in xDrip ha funzioni molto diverse a seconda del sensore.</p><h3 id="g6-and-1" tabindex="-1">G6 e 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 e 1 {#g6-and-1}&quot;">​</a></h3><p>La documentazione di riferimento si trova <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">qui</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 e 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 e 1+ {#g7-and-1}&quot;">​</a></h3><p>Questi sensori si fermano da soli dopo 10 giorni e 12 ore. Alcuni trasmettitori con firmware alternativo indicano invece una durata più lunga di 15 giorni e 12 ore; xDrip lo rileva automaticamente dal firmware del trasmettitore, non è un&#39;impostazione che scegli tu.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h3><p>xDrip non è in grado di fermare un sensore Libre; in realtà questo sensore non si può fermare: se non si guasta, funziona per tutta la sua durata e si ferma da solo dopo 14 giorni e 12 ore.</p><p>L&#39;arresto del sensore in xDrip serve solo a invalidare le calibrazioni precedenti. Questa operazione è necessaria e consigliata ogni volta che sostituisci il sensore.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Stop Sensore</p></div><p>Conferma STOP SENSORE, a meno che tu non voglia solo <a href="./../calibrate/calibrate.html#reset-all-calibrations">azzerare tutte le calibrazioni</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"> Stop Sensore <span class="symbol"></span></p><p> Ferma il tuo sensore solo quando pensi di rimuoverlo, altrimenti lascialo avviato!</p><p>       <span style="background-color:white;color:black;"> STOP SENSORE </span></p></div><p>Conferma che vuoi fermare il sensore.</p><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Vuoi fermare il sensore?</p><p>       NO    <span style="background-color:white;color:black;"> SI </span></p></div><p>Se cambi idea e il sensore non è ancora scaduto, puoi sempre <a href="./startsensor.html#libre">&quot;riavviarlo&quot;</a>: riprenderà la sessione in corso ed eventualmente chiederà una nuova calibrazione. xDrip non riavvia fisicamente i sensori Libre.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Follower e app compagno <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Follower e app compagno {#followers-and-companion-apps}&quot;">​</a></h3><p>Non ha senso fermare un sensore quando usi un&#39;app follower.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>L&#39;unica eccezione è il <a href="./sync.html#accept-followers-actions">follower xDrip Sync, che può trasmettere il comando di avvio o arresto al sensore vero e proprio se questo è collegato direttamente allo xDrip che fa da master</a>.<br> Non usare Avvia e Ferma sensore con un follower xDrip Sync, a meno che tu non sia certo che la persona con il telefono xDrip master sappia cosa fare con un sensore fermato!</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Ultima modifica 6/7/2026</em></a></p>',22)])])}const g=r(t,[["render",l]]);export{v as __pageData,g as default};
